async function huntMore() {
    // Targets not yet successfully killed or needing re-verification
    const targets = ['Chicken', 'Cow', 'Goblin', 'Imp', 'Butterfly', 'Giant rat'];
    for (const targetName of targets) {
        const res = await bot.attack(targetName);
        if (res.success) {
            while (sdk.getState()?.player?.combat.inCombat) {
                if (sdk.getState()?.player?.hp < 7) {
                    await bot.eatFood();
                }
                await sdk.waitForStateUpdate();
            }
        }
    }
}
await huntMore();

async function huntAndMove() {
    const targets = [
        { name: 'Butterfly', loc: [3222, 3217] },
        { name: 'Chicken', loc: [3225, 3215] },
        { name: 'Cow', loc: [3210, 3210] },
        { name: 'Goblin', loc: [3215, 3205] },
        { name: 'Imp', loc: [3210, 3215] }
    ];

    for (const target of targets) {
        await bot.walkTo(target.loc[0], target.loc[1]);
        const res = await bot.attack(target.name);
        if (res.success) {
            while (sdk.getState()?.player?.combat.inCombat) {
                if (sdk.getState()?.player?.hp < 7) {
                    await bot.eatFood();
                }
                await sdk.waitForStateUpdate();
            }
        }
    }
}
await huntAndMove();

